  AND EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('freeholder_merchant_fee_birth_guard()') AND p.provolatile='v' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='9883723488eed7e57ae2af972c9f8553a5dd16128ed17dbf9e657f77cde37d0f')
